import itertools, json
Aopts = ["KNR","MNP","LMQ","LNR","MNR"]
Bopts = ["KLN","NPR","PQR","KMP","LPQ"]
Adays = [{2,6},{1,4,7},{6,7},{3,5},{1,6}]
Bdays = [{4,7},{2},{3,7},{4,5},{3,5,8}]
people = set("KLMNPQR")
west = set("KQR")
As = [a for a in itertools.product(*Aopts) if len(set(a)) == 5]
Bs = [b for b in itertools.product(*Bopts) if len(set(b)) == 5]
counts = {}
witness = {}
total = 0
for a in As:
    for b in Bs:
        overlap = set(a) & set(b)
        if len(overlap) != 3 or len(overlap & west) != 1:
            continue
        total += 1
        days = {p:set() for p in people}
        for p,d in zip(a, Adays): days[p].update(d)
        for p,d in zip(b, Bdays): days[p].update(d)
        n = sum(len(d) >= 3 for d in days.values())
        counts[n] = counts.get(n,0) + 1
        witness.setdefault(n, {"A":"".join(a),"B":"".join(b)})
lo, hi = min(counts), max(counts)
result = {"feasible_linkages":total,"bounds":[lo,hi],"low_witness":witness[lo],"high_witness":witness[hi],"decision":"confirmed" if lo >= 3 else "excluded" if hi < 3 else "undetermined"}
# Independent endpoint verification using date-wise credited person sets.
for n in (lo,hi):
    w = witness[n]
    credited = {p:0 for p in people}
    for day in range(1,9):
        present = {p for p,d in zip(w["A"], Adays) if day in d} | {p for p,d in zip(w["B"], Bdays) if day in d}
        for p in present: credited[p] += 1
    assert sum(v >= 3 for v in credited.values()) == n
assert total == sum(counts.values())
print(json.dumps(result))
print("distribution", sorted(counts.items()))

